"use client";

import { memo, useCallback, useMemo, useState } from "react";
import { settingsStore, type KnowledgeItem } from "@/app/_data/settings";
import {
  Field,
  Group,
  Modal,
  SaveBar,
  Segmented,
  Textarea,
  TextInput,
  Toggle,
} from "../_components/ui";
import { saveSection } from "../blob-actions";
import { approveKnowledge, deleteKnowledge, revokeKnowledgeApproval, saveKnowledge } from "./actions";
import { mergeKeepingOrder } from "@/lib/merge-list";
import { DEFAULT_INTAKE_PROMPT } from "@/lib/agent/intake";
import { GapsBlock, type GapDraft, type GapsData } from "./gaps-block";
import { SpecialistsBlock } from "./specialists-block";
import { QualityBlock, type QualityData } from "./quality-block";
import type { SpecialistItem } from "./specialists-actions";

type AssistantConfig = typeof settingsStore.assistant;

export interface AssistantData {
  assistant: AssistantConfig;
  knowledge: KnowledgeItem[];
}

/** Ключ, по которому запись узнаётся независимо от идентификатора. */
function keyOf(k: KnowledgeItem): string {
  return `${k.topic.trim().toLowerCase()}\u0000${k.question.trim().toLowerCase()}`;
}

function newKnowledgeItem(): KnowledgeItem {
  const id =
    typeof crypto !== "undefined" && "randomUUID" in crypto
      ? crypto.randomUUID()
      : `k${Date.now()}-${Math.random().toString(36).slice(2)}`;

  return { id, topic: "", question: "", answer: "", serviceId: null, isActive: true };
}

/**
 * Черновик записи из пробела.
 *
 * Медицинская тема создаётся ВЫКЛЮЧЕННОЙ: справка такой темы уходит пациенту
 * дословно, и включить её можно только после утверждения врачом. Обычная —
 * включённой, как и всякая новая запись: выключенная по умолчанию была
 * ловушкой, администратор заполнял ответ и не понимал, почему ассистент про
 * него не знает.
 */
function draftFromGap(draft: GapDraft): KnowledgeItem {
  return {
    ...newKnowledgeItem(),
    topic: draft.topic.slice(0, 120),
    question: draft.question,
    answer: draft.answer,
    isActive: !draft.medical,
    needsDoctorApproval: draft.medical,
  };
}


/**
 * Одна запись справочника.
 *
 * Вынесена в отдельный компонент под memo: без этого каждое нажатие клавиши
 * перерисовывало весь список. На четырёх сотнях записей ввод шёл рывками —
 * браузер успевал отрисовать не каждый символ.
 */
const KnowledgeRow = memo(function KnowledgeRow({
  item,
  serviceOptions,
  onPatch,
  onDelete,
  used,
  canApprove,
  onApprove,
  onRevoke,
}: {
  item: KnowledgeItem;
  serviceOptions: { id: string; title: string }[];
  onPatch: (id: string, next: Partial<KnowledgeItem>) => void;
  onDelete: (item: KnowledgeItem) => void;
  /**
   * Сколько раз запись составила ответ пациенту. Считается по журналу попыток
   * агента; отдельного счётчика в записи нет намеренно — он разъедется с
   * фактами, и расхождение будет нечем объяснить.
   */
  used: number;
  canApprove: boolean;
  onApprove: (item: KnowledgeItem) => void;
  onRevoke: (item: KnowledgeItem) => void;
}) {
  const k = item;
  /**
   * Медицинская запись без утверждения врача включаться не должна — и не
   * может: сервер такую отправку отклоняет. Переключатель здесь заблокирован,
   * чтобы человек узнал об этом до сохранения, а не из ошибки после.
   */
  const awaitingDoctor = Boolean(k.needsDoctorApproval) && !k.approvedAt;
  return (
    <li className="border-border-soft rounded-lg border p-3">
      {/*
        Ряд переносится на узком экране. Прежде здесь было четыре элемента в
        одну строку без переноса: поле темы, список услуг с длинными
        названиями, переключатель и кнопка. На телефоне ряд оказывался шире
        экрана, и вся страница начинала ездить по горизонтали.
      */}
      <div className="flex flex-wrap items-center gap-3">
        <TextInput
          value={k.topic}
          onChange={(e) => onPatch(k.id, { topic: e.target.value })}
          className="min-w-[160px] flex-1 py-1.5 font-medium sm:max-w-[220px] sm:flex-none"
        />
        <select
          value={k.serviceId ?? ""}
          onChange={(e) => onPatch(k.id, { serviceId: e.target.value || null })}
          className="border-border-input bg-surface min-w-0 max-w-full rounded-md border px-2.5 py-1.5 text-sm outline-none sm:ml-auto"
        >
          <option value="">без услуги</option>
          {serviceOptions.map((s) => (
            <option key={s.id} value={s.id}>
              {s.title}
            </option>
          ))}
        </select>
        <div className="flex items-center gap-1.5">
          <Toggle
            checked={k.isActive && !awaitingDoctor}
            onChange={(v) => {
              if (awaitingDoctor) return;
              onPatch(k.id, { isActive: v });
            }}
            label={`${k.topic} активна`}
          />
          <button
            type="button"
            onClick={() => onDelete(k)}
            aria-label={`Удалить запись ${k.topic || "без темы"}`}
            className="text-text-subtle hover:text-accent-text flex h-9 w-9 items-center justify-center text-sm"
          >
            ×
          </button>
        </div>
      </div>
      <TextInput
        value={k.question}
        onChange={(e) => onPatch(k.id, { question: e.target.value })}
        placeholder="Вопрос пациента"
        className="mt-2 py-1.5"
      />
      <Textarea
        value={k.answer}
        onChange={(e) => onPatch(k.id, { answer: e.target.value })}
        placeholder="Ответ — дословно так, как отвечает ассистент"
        rows={2}
        className="mt-2"
      />
      {/*
        Польза записи: сколько раз она составила ответ. Ноль — тоже ответ:
        либо об этом не спрашивают, либо подбор запись не находит, и тогда
        дело в формулировке вопроса, а не в тексте справки.
      */}
      <div className="text-text-subtle mt-1.5 text-2xs">
        {used > 0 ? `ответов с ней: ${used}` : "ни разу не пригодилась"}
      </div>
      {/*
        Медицинская запись: кто её утвердил и когда. Ассистент отвечает такой
        справкой дословно, поэтому утверждает её врач, а не тот, кто быстрее
        набрал текст в переписке. Правка текста утверждение снимает.
      */}
      {k.needsDoctorApproval ? (
        <div className="mt-2 flex flex-wrap items-center gap-2">
          <span className={`text-2xs ${awaitingDoctor ? "text-accent-text" : "text-text-subtle"}`}>
            {awaitingDoctor
              ? "Медицинская тема · ждёт утверждения врача, включить нельзя"
              : `Медицинская тема · утвердил(а) ${k.approvedByName ?? "врач"}`}
          </span>
          {canApprove ? (
            <button
              type="button"
              onClick={() => (awaitingDoctor ? onApprove(k) : onRevoke(k))}
              className="border-border text-text-muted hover:bg-hover rounded-md border px-2.5 py-1 text-2xs"
            >
              {awaitingDoctor ? "Утвердить" : "Отозвать утверждение"}
            </button>
          ) : null}
        </div>
      ) : null}
    </li>
  );
});

export function AssistantClient({
  initial,
  serviceOptions,
  gaps,
  quality,
  usage,
  usageSince,
  canApprove,
  specialists,
  staffOptions,
}: {
  initial: AssistantData;
  serviceOptions: { id: string; title: string }[];
  gaps: GapsData;
  /** Что нашла ночная проверка ответов ассистента и что с этим сделал человек. */
  quality: QualityData;
  /** Кому ассистент пересылает вопросы, на которые не отвечает сам. */
  specialists: SpecialistItem[];
  /** Сотрудники клиники: из них выбирают адресата. */
  staffOptions: { id: string; name: string; specialty: string }[];
  /** Сколько ответов составила каждая запись за срок разбора пробелов. */
  usage: Record<string, number>;
  /** С какого момента журнал ведётся: до него счёт был нулевым у всех. */
  usageSince: string | null;
  /** Врач или владелец: только они утверждают медицинские справки. */
  canApprove: boolean;
}) {
  const [assistant, setAssistant] = useState<AssistantConfig>(() =>
    structuredClone(initial.assistant),
  );
  const [knowledge, setKnowledge] = useState<KnowledgeItem[]>(() =>
    structuredClone(initial.knowledge),
  );
  const [query, setQuery] = useState("");
  const [stopDraft, setStopDraft] = useState("");
  const [dirtyKnowledgeIds, setDirtyKnowledgeIds] = useState<Set<string>>(() => new Set());
  const [persistedKnowledgeIds, setPersistedKnowledgeIds] = useState<Set<string>>(
    () => new Set(initial.knowledge.map((item) => item.id)),
  );
  const [deleteTarget, setDeleteTarget] = useState<KnowledgeItem | null>(null);
  const [isDeleting, setIsDeleting] = useState(false);
  const [deleteError, setDeleteError] = useState<string | null>(null);

  const filtered = useMemo(() => {
    const q = query.trim().toLowerCase();
    if (!q) return knowledge;
    return knowledge.filter(
      (k) =>
        k.topic.toLowerCase().includes(q) ||
        k.question.toLowerCase().includes(q) ||
        k.answer.toLowerCase().includes(q),
    );
  }, [knowledge, query]);

  /**
   * Проверяем до отправки и называем строку. Сервер отвергает запись без темы,
   * но раньше это выяснялось уже после нажатия: сохранение падало целиком, а
   * на экране появлялось «Не удалось сохранить» — человек считал, что запись
   * потерялась.
   */
  /** Отказ на утверждении врача — отдельно от проверки формы. */
  const [approvalError, setApprovalError] = useState<string | null>(null);

  const noTopic = knowledge.find((k) => !k.topic.trim());
  const noAnswer = knowledge.find((k) => k.isActive && k.answer.trim().length === 0);
  const error = noTopic
    ? `Заполните тему у записи${noTopic.question.trim() ? ` «${noTopic.question.trim().slice(0, 40)}»` : " без темы"}`
    : noAnswer
      ? `У активной записи «${noAnswer.topic.trim()}» должен быть ответ`
      : null;

  /**
   * Ссылки на обработчики держим постоянными: memo на строке списка не даст
   * ничего, если при каждом нажатии в неё приходит новая функция.
   */
  const patchKnowledge = useCallback((id: string, next: Partial<KnowledgeItem>) => {
    setKnowledge((ks) => ks.map((k) => (k.id === id ? { ...k, ...next } : k)));
    setDirtyKnowledgeIds((ids) => new Set(ids).add(id));
  }, []);

  const requestDelete = useCallback((item: KnowledgeItem) => {
    setDeleteTarget(item);
    setDeleteError(null);
  }, []);

  /**
   * Утверждение врача — отдельное действие, а не часть общего «Сохранить».
   *
   * Врач утверждает конкретный текст, а не всё, что администратор успел
   * наменять в форме. Поэтому отметка ставится сразу и отдельно; несохранённые
   * правки в других строках она не трогает.
   */
  const applyApproval = useCallback(
    async (item: KnowledgeItem, action: (id: string) => Promise<KnowledgeItem[]>) => {
      setApprovalError(null);
      try {
        const saved = await action(item.id);
        setKnowledge((current) => mergeKeepingOrder(current, saved, keyOf));
      } catch (e) {
        setApprovalError((e as Error)?.message ?? "Не удалось изменить утверждение");
      }
    },
    [],
  );

  const approveEntry = useCallback(
    (item: KnowledgeItem) => void applyApproval(item, approveKnowledge),
    [applyApproval],
  );
  const revokeEntry = useCallback(
    (item: KnowledgeItem) => void applyApproval(item, revokeKnowledgeApproval),
    [applyApproval],
  );

  function removeDraft(id: string) {
    setKnowledge((ks) => ks.filter((k) => k.id !== id));
    setDirtyKnowledgeIds((ids) => {
      const next = new Set(ids);
      next.delete(id);
      return next;
    });
  }

  async function confirmDeleteKnowledge() {
    if (!deleteTarget) return;
    setDeleteError(null);
    if (!persistedKnowledgeIds.has(deleteTarget.id)) {
      removeDraft(deleteTarget.id);
      setDeleteTarget(null);
      return;
    }

    setIsDeleting(true);
    try {
      const nextKnowledge = await deleteKnowledge(deleteTarget.id);
      setKnowledge(nextKnowledge);
      setPersistedKnowledgeIds(new Set(nextKnowledge.map((item) => item.id)));
      setDirtyKnowledgeIds((ids) => {
        const next = new Set(ids);
        next.delete(deleteTarget.id);
        return next;
      });
      setDeleteTarget(null);
    } catch (e) {
      console.error(e);
      setDeleteError("Не удалось удалить запись. Обновите страницу и попробуйте ещё раз.");
    } finally {
      setIsDeleting(false);
    }
  }

  return (
    <div className="flex max-w-[820px] flex-col gap-5">
      <Group title="Режим">
        <Field label="Работа ассистента">
          <Segmented
            value={assistant.mode}
            onChange={(v) => setAssistant({ ...assistant, mode: v })}
            options={[
              { value: "drafts", label: "Только черновики" },
              { value: "on", label: "Автономно" },
              { value: "off", label: "Выключен" },
            ]}
          />
        </Field>
        <Field label="Приветствие" htmlFor="a-greeting">
          <Textarea
            id="a-greeting"
            rows={2}
            value={assistant.greeting}
            onChange={(e) => setAssistant({ ...assistant, greeting: e.target.value })}
          />
        </Field>
        <Field label="Подпись" htmlFor="a-sign">
          <TextInput
            id="a-sign"
            value={assistant.signature}
            onChange={(e) => setAssistant({ ...assistant, signature: e.target.value })}
          />
        </Field>
      </Group>

      <Group
        title="Инструкция ассистента"
        hint="как вести разговор и что спрашивать при записи"
      >
        <p className="text-text-muted text-sm">
          Это правила поведения, а не ответы на вопросы: ответы ассистент берёт из базы знаний ниже.
          Базовые ограничения работают всегда и отсюда не отключаются — ассистент не называет время
          приёма, не подтверждает запись, не выдумывает цены и передаёт человеку медицинские вопросы.
        </p>
        <Field label="Текст инструкции" htmlFor="a-prompt">
          <Textarea
            id="a-prompt"
            rows={12}
            value={assistant.prompt}
            onChange={(e) => setAssistant({ ...assistant, prompt: e.target.value })}
            placeholder={DEFAULT_INTAKE_PROMPT}
          />
        </Field>
        <div className="flex items-center gap-3">
          <button
            type="button"
            onClick={() => setAssistant({ ...assistant, prompt: DEFAULT_INTAKE_PROMPT })}
            className="border-border text-text-muted hover:bg-hover rounded-md border px-3 py-2 text-sm"
          >
            Вставить образец
          </button>
          <span className="text-text-subtle text-sm">
            Пусто — ассистент работает по образцу.
          </span>
        </div>
      </Group>

      <Group title="Стоп-слова" hint="при них ассистент молчит и зовёт человека">
        <div className="flex flex-wrap gap-1.5">
          {assistant.stopWords.map((word) => (
            <span
              key={word}
              className="border-border bg-hover text-text-muted inline-flex items-center gap-1.5 rounded-md border px-2 py-1 text-sm"
            >
              {word}
              <button
                type="button"
                onClick={() =>
                  setAssistant({
                    ...assistant,
                    stopWords: assistant.stopWords.filter((w) => w !== word),
                  })
                }
                className="text-text-subtle hover:text-text"
                aria-label={`Убрать ${word}`}
              >
                ×
              </button>
            </span>
          ))}
        </div>
        <form
          className="flex gap-2"
          onSubmit={(e) => {
            e.preventDefault();
            const w = stopDraft.trim().toLowerCase();
            if (w && !assistant.stopWords.includes(w)) {
              setAssistant({ ...assistant, stopWords: [...assistant.stopWords, w] });
            }
            setStopDraft("");
          }}
        >
          <TextInput
            value={stopDraft}
            onChange={(e) => setStopDraft(e.target.value)}
            placeholder="Добавить стоп-слово"
            className="max-w-[240px]"
          />
          <button
            type="submit"
            className="border-border text-text-muted hover:bg-hover rounded-md border px-3 py-2 text-sm"
          >
            Добавить
          </button>
        </form>
      </Group>

      {/*
        Пробелы — над базой знаний: сначала видно, чего не хватает, потом
        редактор, куда падает черновик. Кнопка в этом блоке ничего не
        сохраняет — она добавляет строку ниже, и её надо прочитать.
      */}
      <SpecialistsBlock initial={specialists} staffOptions={staffOptions} />

      <GapsBlock
        data={gaps}
        onDraft={(draft) => {
          const item = draftFromGap(draft);
          setQuery("");
          setKnowledge((items) => [...items, item]);
          setDirtyKnowledgeIds((ids) => new Set(ids).add(item.id));
        }}
      />

      {/*
        Контроль качества — рядом с пробелами и по той же причине: и то, и
        другое кончается одним действием, записью в справочнике. «Ответил без
        справки» и «спросили, а ответить было нечем» — это один и тот же
        пробел, увиденный с разных сторон.
      */}
      <QualityBlock
        data={quality}
        onDraft={(draft) => {
          const item = draftFromGap(draft);
          setQuery("");
          setKnowledge((items) => [...items, item]);
          setDirtyKnowledgeIds((ids) => new Set(ids).add(item.id));
        }}
      />

      <Group title="База знаний" hint="ассистент отвечает только этими текстами">
        {/*
          Ноль ответов у записи может означать «не спрашивают», а может —
          «журнала тогда ещё не было». Разница важная: по первому прочтению
          запись удаляют.
        */}
        {usageSince ? (
          <p className="text-text-subtle text-2xs">
            Счёт ответов ведётся с{" "}
            {new Intl.DateTimeFormat("ru-RU", { day: "numeric", month: "long" }).format(
              new Date(usageSince),
            )}
            : раньше журнала попыток не было.
          </p>
        ) : (
          <p className="text-text-subtle text-2xs">
            Журнал попыток ещё пуст — счёт ответов появится, когда ассистент начнёт отвечать.
          </p>
        )}
        <input
          value={query}
          onChange={(e) => setQuery(e.target.value)}
          placeholder="Поиск по темам и ответам"
          className="border-border-input bg-surface placeholder:text-text-subtle w-full max-w-[320px] rounded-md border px-3 py-2 text-sm outline-none"
        />
        <ul className="flex flex-col gap-3">
          {filtered.length === 0 ? (
            <li className="text-text-subtle text-sm">Ничего не нашлось.</li>
          ) : (
            filtered.map((k) => (
              <KnowledgeRow
                key={k.id}
                item={k}
                serviceOptions={serviceOptions}
                onPatch={patchKnowledge}
                onDelete={requestDelete}
                used={usage[k.id] ?? 0}
                canApprove={canApprove}
                onApprove={approveEntry}
                onRevoke={revokeEntry}
              />
            ))
          )}
        </ul>
        <button
          type="button"
          onClick={() => {
            const item = newKnowledgeItem();
            setQuery("");
            setKnowledge((items) => [
              ...items,
              // Новая запись сразу включена: выключенная по умолчанию — ловушка.
              // Администратор заполнял ответ, сохранял и не понимал, почему
              // ассистент про него не знает.
              item,
            ]);
            setDirtyKnowledgeIds((ids) => new Set(ids).add(item.id));
          }}
          className="border-border text-text-muted hover:bg-hover self-start rounded-md border px-3 py-1.5 text-sm"
        >
          + Добавить запись
        </button>
      </Group>

      {approvalError ? <p className="text-accent-text text-sm">{approvalError}</p> : null}

      <div className="flex items-center gap-3">
        <SaveBar
          error={error}
          onSave={async () => {
            // Конфигурацию и знания сохраняем в их настоящие места: поведение — в
            // настройку, тексты — в таблицу, которую читает агент.
            await saveSection("assistant", { assistant });
            if (dirtyKnowledgeIds.size > 0) {
              const changedKnowledge = knowledge.filter((item) => dirtyKnowledgeIds.has(item.id));
              const saved = await saveKnowledge(changedKnowledge);
              /**
               * Порядок на экране сохраняем свой. Сервер отдаёт список по
               * алфавиту, и добавленная в конец запись после сохранения
               * уезжала в середину шести десятков строк — выглядело так,
               * будто она потерялась.
               */
              setKnowledge((current) => mergeKeepingOrder(current, saved, keyOf));
              setPersistedKnowledgeIds(new Set(saved.map((item) => item.id)));
              setDirtyKnowledgeIds(new Set());
            }
          }}
        />
      </div>

      <Modal
        open={Boolean(deleteTarget)}
        onClose={() => {
          if (!isDeleting) {
            setDeleteTarget(null);
            setDeleteError(null);
          }
        }}
        title="Удалить запись"
        description="Запись будет безвозвратно удалена из базы знаний и больше не будет доступна ассистенту."
        footer={
          <>
            <button
              type="button"
              onClick={() => {
                setDeleteTarget(null);
                setDeleteError(null);
              }}
              disabled={isDeleting}
              className="border-border text-text-muted hover:bg-hover rounded-md border px-3.5 py-2 text-sm disabled:opacity-45"
            >
              Отмена
            </button>
            <button
              type="button"
              onClick={confirmDeleteKnowledge}
              disabled={isDeleting}
              className="bg-accent text-accent-contrast hover:bg-accent-hover rounded-md px-3.5 py-2 text-sm font-medium disabled:opacity-45"
            >
              {isDeleting ? "Удаляем…" : "Удалить"}
            </button>
          </>
        }
      >
        <div className="flex flex-col gap-2">
          <p className="text-text-muted text-sm leading-relaxed">
            {deleteTarget?.topic ? `Тема: ${deleteTarget.topic}` : "Эта запись ещё без темы."}
          </p>
          {deleteError ? <p className="text-accent-text text-sm">{deleteError}</p> : null}
        </div>
      </Modal>
    </div>
  );
}
